// theme origin metadata: generated by scripts/generate-themes.ts, do not edit.
// Provenance of every built-in colour theme: how each standard palette came to
// be, as data. It is not a recipe for regenerating a palette (an authored
// palette is not promised to reproduce from one seed), not an active-theme
// detector, and not a contrast API. bun run themes:origins rewrites this block.

/** M3's baseline seed colour: the source of the baseline theme and of the eight scheme variants. */
export const BASELINE_SEED = "#6750a4";

/** The dynamic-scheme recipe a generated theme's standard palette was built with. */
export type ThemeOriginVariant =
  | "tonal-spot" | "neutral" | "vibrant" | "expressive" | "fidelity"
  | "content" | "monochrome" | "rainbow" | "fruit-salad";

/**
 * A theme whose standard palette the generator builds from a seed. `contrast`
 * is the generation input of the default block (0 standard, 1 high), not the
 * page's effective level; `secondary` and `tertiary` are the extra seed inputs
 * a two-colour theme carries.
 */
export interface GeneratedThemeOrigin {
  /** The record discriminant: this palette was generated. */
  readonly kind: "generated";
  /** Source colour, lowercase `#rrggbb`. */
  readonly seed: string;
  readonly variant: ThemeOriginVariant;
  readonly contrast: number;
  readonly secondary?: string;
  readonly tertiary?: string;
}

/**
 * The baseline theme. Its standard palette is maintained as the published
 * token table; the seed describes its documented association, and this
 * metadata does not promise the table regenerates from it.
 */
export interface BaselineThemeOrigin {
  /** The record discriminant: the maintained baseline palette. */
  readonly kind: "baseline";
  readonly seed: "#6750a4";
  readonly variant: "tonal-spot";
  readonly contrast: 0;
}

/**
 * A hand-authored palette. `seed` is the documented source seed where the
 * theme's own source records one, `null` where it does not; no verified
 * recipe exists, so `variant` and `contrast` are `null` rather than a guess.
 */
export interface AuthoredThemeOrigin {
  /** The record discriminant: an authored palette. */
  readonly kind: "authored";
  readonly seed: string | null;
  readonly variant: null;
  readonly contrast: null;
}

/** How one built-in theme's standard palette came to be. */
export type ThemeOrigin = GeneratedThemeOrigin | BaselineThemeOrigin | AuthoredThemeOrigin;

/** Every theme name that ships a built-in stylesheet. */
export type BuiltInThemeName =
  | "baseline"
  | "neutral"
  | "vibrant"
  | "expressive"
  | "fidelity"
  | "content"
  | "monochrome"
  | "rainbow"
  | "fruit-salad"
  | "desert"
  | "summer"
  | "brownbeige"
  | "sageivory"
  | "tealcaramel"
  | "highcontrast"
  | "autumn"
  | "forest"
  | "ocean"
  | "spring"
  | "sunset";

